const COLOR_CSS=":host{color:var(--ink);background:transparent;--accent:var(--tabbit-card-primary);--accent-alt:var(--tabbit-card-secondary);--ink:var(--tabbit-card-foreground);--muted:var(--tabbit-card-muted);--paper:var(--tabbit-card-background);--on-accent:var(--tabbit-card-on-primary);--panel-paper:var(--tabbit-card-background);--button-paper:var(--tabbit-card-background);--line:color-mix(in srgb,var(--tabbit-card-foreground) 18%,transparent);--soft:color-mix(in srgb,var(--tabbit-card-primary) 12%,var(--tabbit-card-background));--danger:var(--tabbit-card-foreground);--design-accent:var(--accent);--design-accentAlt:var(--accent-alt);--design-ink:var(--ink);--design-muted:var(--muted);--design-surface:var(--paper);--design-panel:var(--panel-paper);--design-stroke:var(--line);--design-onAccent:var(--on-accent);}.card{background:transparent}.card:has(>.infra-panel)>:not(.infra-panel){visibility:hidden}";
const CSS=".card{box-sizing:border-box;width:100%;height:100%;min-width:0;min-height:0;display:flex;flex-direction:column;overflow:hidden;padding:10px;background:transparent;color:var(--ink);font:12px/1.4 system-ui,-apple-system,\"PingFang SC\",\"Microsoft YaHei\",sans-serif}\n.card *{box-sizing:border-box}\n.view{flex:1;min-width:0;min-height:0;display:flex;flex-direction:column;gap:8px}\nbutton{font:inherit;color:inherit;cursor:pointer}\n.btn{min-height:30px;padding:0 12px;border:1px solid var(--line);border-radius:8px;background:var(--soft);color:var(--ink);font-weight:600;white-space:nowrap}\n.btn.sm{min-height:28px;padding:0 9px;font-size:12px}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:var(--on-accent)}\n.btn.danger{background:var(--ink);border-color:var(--ink);color:var(--paper)}\n.btn:disabled{opacity:.5;cursor:default}\n.btn:focus-visible,.inp:focus-visible,.pv-row:focus-visible,.sc-main:focus-visible{outline:2px solid var(--accent);outline-offset:1px}\n.brand{display:flex;justify-content:space-between;align-items:center;gap:6px;font-size:11px;font-weight:700;letter-spacing:.04em;color:var(--accent)}\n.cnt{color:var(--muted);font-weight:500;letter-spacing:0}\n.lbl{font-size:11px;color:var(--muted)}\n.err{flex:none;padding:5px 8px;border:1px solid var(--ink);border-radius:8px;background:var(--soft);font-weight:600;line-height:1.35}\n.hint{font-size:11px;color:var(--muted)}\n\n/* \u9996\u9875 */\n.empty{justify-content:center;align-items:flex-start;gap:8px}\n.empty-t{font-size:17px;font-weight:800}\n.empty-d{color:var(--muted);line-height:1.5}\n.info{grid-area:info;display:flex;flex-direction:column;gap:6px;min-width:0}\n.title{font-size:15px;font-weight:700;line-height:1.3;overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow-wrap:anywhere}\n.total{display:flex;align-items:baseline;gap:6px;flex-wrap:wrap;min-width:0}\n.dur{display:inline-flex;align-items:baseline;white-space:nowrap}\n.dn{font-size:28px;font-weight:800;line-height:1.05;font-variant-numeric:tabular-nums}\n.du{font-size:12px;color:var(--muted);margin:0 3px 0 1px}\n.bar{display:flex;gap:2px;height:6px;border-radius:3px;overflow:hidden;flex:none}\n.seg{display:block;min-width:2px;border-radius:2px}\n.seg.s0{background:var(--accent)}\n.seg.s1{background:var(--accent-alt)}\n.seg.s2{background:var(--line)}\n.actions{grid-area:act;display:flex;gap:6px;flex:none;margin-top:auto}\n.actions .btn{flex:1 1 0;min-width:0;padding:0 6px}\n.pv{grid-area:pv;flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:4px}\n.pv-row{flex:none;display:grid;grid-template-columns:18px minmax(0,1fr) auto;gap:6px;align-items:start;width:100%;text-align:left;padding:6px;border:1px solid var(--line);border-radius:8px;background:var(--soft);color:var(--ink)}\n.pv-n{font-weight:800;color:var(--accent);font-variant-numeric:tabular-nums}\n.pv-b{display:flex;flex-direction:column;gap:1px;min-width:0}\n.pv-v,.pv-l{display:-webkit-box;-webkit-box-orient:vertical;overflow:hidden;overflow-wrap:anywhere;-webkit-line-clamp:2}\n.pv-v{font-weight:600}\n.pv-v.dim{color:var(--muted);font-weight:400}\n.pv-l{color:var(--muted);-webkit-line-clamp:1}\n.pv-s{font-size:11px;color:var(--muted);white-space:nowrap;font-variant-numeric:tabular-nums}\n.pv-empty{padding:8px;border:1px dashed var(--line);border-radius:8px;color:var(--muted);line-height:1.5}\n\n.card[data-size=\"3x3\"] .pv{display:none}\n.card[data-size=\"3x3\"] .dn{font-size:26px}\n.card[data-size=\"6x3\"] .home{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.15fr);grid-template-rows:minmax(0,1fr) auto;grid-template-areas:\"info pv\" \"act pv\";column-gap:12px;row-gap:8px}\n.card[data-size=\"6x3\"] .pv-v{-webkit-line-clamp:1}\n.card[data-size=\"6x3\"] .info{overflow:auto;min-height:0}\n.card[data-size=\"6x6\"] .pv-l{-webkit-line-clamp:2}\n.card[data-size=\"6x6\"]{padding:14px}\n.card[data-size=\"6x6\"] .title{font-size:18px}\n.card[data-size=\"6x6\"] .dn{font-size:36px}\n.card[data-size=\"6x6\"] .pv-row{padding:8px}\n\n/* \u7f16\u8f91 / \u5207\u6362 / \u65b0\u5efa */\n.ed-head{display:flex;align-items:center;gap:6px;flex:none}\n.ed-name{flex:1;min-width:0;font-weight:700;font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}\n.ed-head .btn:last-child{margin-left:auto}\n.card[data-size^=\"3x\"] .ed-name{display:none}\n.ed-body{position:relative;flex:1;min-height:0;min-width:0;overflow:auto;display:flex;flex-direction:column;gap:8px}\n.ed-foot{display:flex;align-items:center;gap:8px;flex:none}\n.ed-foot .btn{flex:1 1 auto;min-width:0}\n.sum{flex:none;display:flex;flex-direction:column;align-items:flex-end;line-height:1.15;max-width:48%}\n.sum-v{font-size:13px;font-weight:800;white-space:nowrap;font-variant-numeric:tabular-nums}\n\n.inp{width:100%;min-width:0;padding:6px 8px;border:1px solid var(--line);border-radius:8px;background:var(--panel-paper);color:var(--ink);font:inherit}\n.inp::placeholder{color:var(--muted);opacity:.8}\n.ta{display:block;resize:none;min-height:50px;line-height:1.35}\n.title-inp{font-weight:700;font-size:13px}\n.fld{display:flex;flex-direction:column;gap:2px;min-width:0}\n.fl{font-size:11px;color:var(--muted);font-weight:600}\n\n.shot{flex:none;display:flex;flex-direction:column;gap:6px;padding:8px;border:1px solid var(--line);border-radius:10px;background:var(--soft)}\n.sh-top{display:flex;align-items:center;gap:6px;flex-wrap:wrap}\n.sh-idx{font-weight:800;color:var(--accent)}\n.sh-start{font-size:11px;color:var(--muted);font-variant-numeric:tabular-nums}\n.sec{margin-left:auto;display:inline-flex;align-items:center;gap:3px}\n.sec-in{width:46px;padding:4px 2px;text-align:center;-moz-appearance:textfield;appearance:textfield}\n.sec-in::-webkit-outer-spin-button,.sec-in::-webkit-inner-spin-button{-webkit-appearance:none;margin:0}\n.su{font-size:11px;color:var(--muted)}\n.btn.step{min-height:26px;width:26px;padding:0;font-size:15px;line-height:1}\n.flds{display:grid;grid-template-columns:minmax(0,1fr);gap:6px}\n.card[data-size^=\"6x\"] .flds{grid-template-columns:minmax(0,1fr) minmax(0,1fr)}\n.sh-act{display:flex;gap:6px;flex-wrap:wrap}\n.sh-act .btn{min-height:26px;padding:0 8px;font-size:11px}\n\n.sc-item{flex:none;display:flex;align-items:flex-start;gap:6px;flex-wrap:wrap;padding:8px;border:1px solid var(--line);border-radius:10px;background:var(--soft)}\n.sc-item.cur{border-color:var(--accent);box-shadow:inset 0 0 0 1px var(--accent)}\n.sc-main{flex:1 1 90px;min-width:0;display:flex;flex-direction:column;gap:2px;text-align:left;padding:0;border:0;background:none;color:var(--ink)}\n.sc-t{font-weight:700;font-size:13px;line-height:1.3;overflow-wrap:anywhere}\n.sc-flag{display:inline-block;margin-right:5px;padding:0 5px;border-radius:4px;background:var(--accent);color:var(--on-accent);font-size:10px;font-weight:700;vertical-align:1px}\n.sc-m,.sc-d{font-size:11px;color:var(--muted)}\n.sc-del{display:flex;gap:4px;flex:none;margin-left:auto}\n.sc-del .btn{min-height:26px;padding:0 8px;font-size:11px}\n";
function vsList(s){return s&&Array.isArray(s.scripts)?s.scripts:[]}
function vsShots(sc){return sc&&Array.isArray(sc.shots)?sc.shots:[]}
function vsSec(v){const n=Math.round(Number(v));return isFinite(n)&&n>0?n:0}
function vsTotal(sc){return vsShots(sc).reduce((a,x)=>a+vsSec(x&&x.sec),0)}
function vsPad(n){return n<10?'0'+n:''+n}
function vsClock(t){
  t=vsSec(t);
  const h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=t%60;
  return h?h+':'+vsPad(m)+':'+vsPad(s):m+':'+vsPad(s);
}
function vsText(t){
  t=vsSec(t);
  const h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=t%60;
  if(h)return h+'时'+vsPad(m)+'分'+vsPad(s)+'秒';
  if(m)return m+'分'+vsPad(s)+'秒';
  return s+'秒';
}
function vsDur(el,t){
  t=vsSec(t);
  const h=Math.floor(t/3600),m=Math.floor(t%3600/60),s=t%60;
  const w=el('span',{class:'dur'});
  const num=v=>el('b',{class:'dn'},String(v));
  const unit=u=>el('span',{class:'du'},u);
  if(h){w.appendChild(num(h));w.appendChild(unit('时'))}
  if(h||m){w.appendChild(num(h?vsPad(m):m));w.appendChild(unit('分'))}
  w.appendChild(num((h||m)?vsPad(s):s));
  w.appendChild(unit('秒'));
  return w;
}
function vsBar(el,shots){
  const b=el('div',{class:'bar'});
  shots.forEach((x,i)=>{
    const seg=el('i',{class:'seg s'+(i%2)});
    seg.style.flex=Math.max(vsSec(x.sec),1)+' 1 0px';
    b.appendChild(seg);
  });
  if(!shots.length){
    const seg=el('i',{class:'seg s2'});
    seg.style.flex='1 1 0px';
    b.appendChild(seg);
  }
  return b;
}
function vsActive(s){
  const a=vsList(s);
  const id=s&&s.activeId;
  return a.find(x=>x.id===id)||a[0]||null;
}
function vsClone(sc){
  return {
    id:sc.id,
    title:sc.title||'',
    shots:vsShots(sc).map(x=>({
      id:x.id,
      visual:x.visual||'',
      line:x.line||'',
      sec:vsSec(x.sec)>0?String(vsSec(x.sec)):''
    }))
  };
}
function vsClean(d,today){
  return {
    id:d.id,
    title:String(d.title||'').trim(),
    updatedAt:today,
    shots:vsShots(d).map(x=>({
      id:x.id,
      visual:String(x.visual||''),
      line:String(x.line||''),
      sec:vsSec(x.sec)
    }))
  };
}
function vsSorted(a){
  return a.map((x,i)=>({x:x,i:i})).sort((p,q)=>String(q.x.updatedAt||'').localeCompare(String(p.x.updatedAt||''))||q.i-p.i).map(o=>o.x);
}

function mount(ctx){
  const {root,el,state,ui,commit,redraw,uid,day}=ctx;
  const scripts=vsList(state);
  let bodyEl=null,after=null;
  const refs={starts:[],sum:null,save:null};

  function keep(){if(bodyEl)ui.sc=bodyEl.scrollTop}
  function go(patch){keep();Object.assign(ui,patch);redraw()}
  function fail(e){
    ui.err='保存失败：'+(e&&e.message?e.message:'请稍后重试');
    redraw();
    return false;
  }

  function persist(patch){
    const d=ui.draft;
    if(!d)return Promise.resolve(false);
    keep();
    if(!String(d.title||'').trim()){
      ui.err='请先填写脚本名称';
      redraw();
      return Promise.resolve(false);
    }
    const clean=vsClean(d,day());
    const nu=Object.assign({},ui,{err:'',dirty:false,delShot:null},patch||{});
    return commit(s=>{
      let hit=false;
      const out=vsList(s).map(x=>{
        if(x.id===clean.id){hit=true;return clean}
        return x;
      });
      if(!hit)out.push(clean);
      return Object.assign({},s,{scripts:out});
    },nu).catch(fail);
  }

  function markDirty(){
    ui.dirty=true;
    if(refs.save){
      refs.save.disabled=false;
      refs.save.textContent='保存';
      refs.save.className='btn sm primary';
    }
  }

  function refreshTimes(){
    const d=ui.draft;
    if(!d)return;
    let acc=0;
    d.shots.forEach((x,i)=>{
      if(refs.starts[i])refs.starts[i].textContent='起 '+vsClock(acc);
      acc+=vsSec(x.sec);
    });
    if(refs.sum)refs.sum.textContent=vsText(acc);
  }

  function openEdit(shotId){
    const sc=vsActive(state);
    if(!sc)return;
    go({view:'edit',draft:vsClone(sc),dirty:false,err:'',sc:0,focusShot:shotId||null,focusField:false,delShot:null});
  }

  function addShot(){
    const d=ui.draft;
    const id=uid();
    d.shots.push({id:id,visual:'',line:'',sec:''});
    persist({focusShot:id,focusField:true});
  }

  function moveShot(i,dir){
    const d=ui.draft;
    const j=i+dir;
    if(j<0||j>=d.shots.length)return;
    const id=d.shots[i].id;
    const t=d.shots[i];
    d.shots[i]=d.shots[j];
    d.shots[j]=t;
    persist({focusShot:id,focusField:false});
  }

  function removeShot(i){
    const d=ui.draft;
    const x=d.shots[i];
    if(ui.delShot!==x.id){go({delShot:x.id});return}
    d.shots.splice(i,1);
    persist({focusShot:null,delShot:null});
  }

  function selectScript(id){
    commit(s=>Object.assign({},s,{activeId:id}),Object.assign({},ui,{view:'home',delScript:null,err:''})).catch(fail);
  }

  function removeScript(id){
    if(ui.delScript!==id){go({delScript:id});return}
    commit(s=>{
      const rest=vsList(s).filter(x=>x.id!==id);
      const cur=s&&s.activeId===id?(rest.length?rest[rest.length-1].id:null):(s&&s.activeId)||null;
      return Object.assign({},s,{scripts:rest,activeId:cur});
    },Object.assign({},ui,{delScript:null,err:''})).catch(fail);
  }

  function createScript(){
    const t=String(ui.newTitle||'').trim();
    if(!t){go({err:'请输入脚本名称'});return}
    const id=uid();
    const sc={id:id,title:t,shots:[],updatedAt:day()};
    commit(s=>Object.assign({},s,{scripts:vsList(s).concat([sc]),activeId:id}),
      Object.assign({},ui,{view:'edit',draft:vsClone(sc),dirty:false,err:'',newTitle:'',sc:0,focusShot:null,focusField:false,delShot:null})
    ).catch(fail);
  }

  function btn(cls,label,fn,extra){
    const b=el('button',Object.assign({class:'btn '+cls,type:'button',onclick:fn},extra||{}),label);
    return b;
  }


  function renderHome(){
    const sc=vsActive(state);
    if(!sc){
      const v=el('div',{class:'view empty'});
      v.appendChild(el('div',{class:'brand'},'视频脚本'));
      v.appendChild(el('div',{class:'empty-t'},'还没有脚本'));
      v.appendChild(el('div',{class:'empty-d'},'新建一个脚本，逐个镜头写画面、台词和大概秒数，还能调整镜头顺序。'));
      v.appendChild(btn('primary','新建脚本',()=>go({view:'new',err:'',newTitle:''})));
      return v;
    }
    const shots=vsShots(sc);
    const total=vsTotal(sc);

    const info=el('div',{class:'info'});
    const brand=el('div',{class:'brand'},el('span',{},'视频脚本'),el('span',{class:'cnt'},shots.length+' 个镜头'));
    const title=el('div',{class:'title'},sc.title||'');
    title.title=sc.title||'';
    const tot=el('div',{class:'total'},el('span',{class:'lbl'},'总时长'),vsDur(el,total));
    info.appendChild(brand);
    info.appendChild(title);
    info.appendChild(tot);
    info.appendChild(vsBar(el,shots));

    const pv=el('div',{class:'pv'});
    if(!shots.length){
      pv.appendChild(el('div',{class:'pv-empty'},'这个脚本还没有镜头，点「打开编辑」添加第一个镜头。'));
    }
    shots.forEach((x,i)=>{
      const b=el('span',{class:'pv-b'});
      const vis=el('span',{class:'pv-v'+(x.visual?'':' dim')},x.visual||'（未写画面）');
      b.appendChild(vis);
      if(x.line)b.appendChild(el('span',{class:'pv-l'},'“'+x.line+'”'));
      const row=el('button',{class:'pv-row',type:'button',onclick:()=>openEdit(x.id)},
        el('span',{class:'pv-n'},String(i+1)),
        b,
        el('span',{class:'pv-s'},vsSec(x.sec)+'秒')
      );
      pv.appendChild(row);
    });

    const act=el('div',{class:'actions'});
    act.appendChild(btn('primary','打开编辑',()=>openEdit()));
    act.appendChild(btn('','切换脚本'+(scripts.length>1?'（'+scripts.length+'）':''),()=>go({view:'list',err:'',delScript:null,sc:0})));

    const v=el('div',{class:'view home'});
    v.appendChild(info);
    v.appendChild(pv);
    v.appendChild(act);
    if(ui.err){info.appendChild(el('div',{class:'err',role:'alert'},'注意：'+ui.err))}
    return v;
  }


  function shotCard(d,x,i){
    const n=d.shots.length;
    const card=el('div',{class:'shot'});
    card.setAttribute('data-id',x.id);

    const start=el('span',{class:'sh-start'});
    refs.starts[i]=start;
    const secIn=el('input',{class:'inp sec-in',type:'number',min:'0',step:'1',inputmode:'numeric',placeholder:'0','aria-label':'镜头'+(i+1)+'大概秒数',
      oninput:e=>{x.sec=e.target.value;markDirty();refreshTimes()}});
    secIn.value=x.sec||'';
    const bump=k=>()=>{
      const v=Math.max(0,vsSec(x.sec)+k);
      x.sec=v>0?String(v):'';
      secIn.value=x.sec;
      markDirty();
      refreshTimes();
    };
    const sec=el('span',{class:'sec'},
      el('button',{class:'btn step',type:'button','aria-label':'减1秒',onclick:bump(-1)},'−'),
      secIn,
      el('span',{class:'su'},'秒'),
      el('button',{class:'btn step',type:'button','aria-label':'加1秒',onclick:bump(1)},'+')
    );
    const top=el('div',{class:'sh-top'},el('span',{class:'sh-idx'},'镜头 '+(i+1)),start,sec);

    const field=(key,label,ph)=>{
      const ta=el('textarea',{class:'inp ta',rows:'2',placeholder:ph,'aria-label':'镜头'+(i+1)+label,
        oninput:e=>{x[key]=e.target.value;markDirty()}});
      ta.value=x[key]||'';
      return el('label',{class:'fld'},el('span',{class:'fl'},label),ta);
    };
    const flds=el('div',{class:'flds'},field('visual','画面','拍什么、怎么拍'),field('line','台词','旁白或对白'));

    const confirming=ui.delShot===x.id;
    const acts=el('div',{class:'sh-act'});
    const up=el('button',{class:'btn sm',type:'button',onclick:()=>moveShot(i,-1)},'↑ 上移');
    const dn=el('button',{class:'btn sm',type:'button',onclick:()=>moveShot(i,1)},'↓ 下移');
    up.disabled=i===0;
    dn.disabled=i===n-1;
    acts.appendChild(up);
    acts.appendChild(dn);
    acts.appendChild(el('button',{class:'btn sm'+(confirming?' danger':''),type:'button',onclick:()=>removeShot(i)},confirming?'确认删除':'删除'));
    if(confirming)acts.appendChild(el('button',{class:'btn sm',type:'button',onclick:()=>go({delShot:null})},'取消'));

    card.appendChild(top);
    card.appendChild(flds);
    card.appendChild(acts);
    return card;
  }

  function renderEdit(){
    const d=ui.draft;
    const v=el('div',{class:'view edit'});

    const save=el('button',{class:'btn sm'+(ui.dirty?' primary':''),type:'button',onclick:()=>persist()},ui.dirty?'保存':'已保存');
    save.disabled=!ui.dirty;
    refs.save=save;
    const head=el('div',{class:'ed-head'},
      el('button',{class:'btn sm',type:'button','aria-label':'保存并返回',onclick:()=>{
        if(ui.dirty)persist({view:'home',draft:null,focusShot:null});
        else go({view:'home',draft:null,focusShot:null,err:''});
      }},'‹ 完成'),
      el('span',{class:'ed-name'},'编辑脚本'),
      save
    );
    v.appendChild(head);
    if(ui.err)v.appendChild(el('div',{class:'err',role:'alert'},'注意：'+ui.err));

    const body=el('div',{class:'ed-body'});
    bodyEl=body;
    const tin=el('input',{class:'inp title-inp',type:'text',placeholder:'脚本名称','aria-label':'脚本名称',
      oninput:e=>{d.title=e.target.value;markDirty()}});
    tin.value=d.title||'';
    body.appendChild(el('label',{class:'fld'},el('span',{class:'fl'},'脚本名称'),tin));

    if(!d.shots.length){
      body.appendChild(el('div',{class:'pv-empty'},'还没有镜头。点下方「添加镜头」，为每个镜头写画面、台词和大概秒数。'));
    }
    d.shots.forEach((x,i)=>body.appendChild(shotCard(d,x,i)));
    v.appendChild(body);

    const sum=el('span',{class:'sum-v'});
    refs.sum=sum;
